Assume $\gamma(x)\neq 0$ and $S\equiv 0$ for $x\ge x_s$ (production stops at $x_s$).
\begin{enumerate}
\item Use \eqref{eq:number_conservation_condition} to show that
\begin{equation}\label{eq:N_of_x}
\mathcal{N}(x)=\frac{Y_2(x)}{2}.
\end{equation}
\item Show that for $x\ge x_s$, the moment equations close as
\begin{equation}\label{eq:moment_odes}
\partial_x Y_2(x)=0,\qquad
\partial_x Y_3(x)=\gamma(x)\big(3Y_2(x)-Y_3(x)\big),\qquad
\partial_x Y_4(x)=\gamma(x)\big(12Y_2(x)-Y_4(x)\big).
\end{equation}
\end{enumerate}
